package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string `json:"query"`
	Category string `json:"category"`
	Limit    int    `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Desc  string `json:"description"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "host=localhost port=5432 user=appuser dbname=products sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeCategory performs basic validation on category input
func sanitizeCategory(cat string) string {
	// Remove obvious dangerous characters but allow alphanumeric and spaces
	cat = strings.ReplaceAll(cat, ";", "")
	cat = strings.ReplaceAll(cat, "--", "")
	return cat
}

// buildSearchQuery constructs the search SQL dynamically
func buildSearchQuery(req SearchRequest) string {
	base := "SELECT id, name, price, description FROM products WHERE 1=1"

	if req.Query != "" {
		// Using parameterized approach for the main query field
		base += " AND name ILIKE '%' || $1 || '%'"
	}

	if req.Category != "" {
		// Category is pre-validated through sanitizeCategory
		clean := sanitizeCategory(req.Category)
		base += fmt.Sprintf(" AND category = '%s'", clean)
	}

	if req.Limit > 0 && req.Limit <= 100 {
		base += fmt.Sprintf(" LIMIT %d", req.Limit)
	} else {
		base += " LIMIT 20"
	}

	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	// Log search for analytics
	log.Printf("Search request: query=%s category=%s limit=%d",
		req.Query, req.Category, req.Limit)

	query := buildSearchQuery(req)

	var rows *sql.Rows
	var err error
	if req.Query != "" {
		rows, err = db.Query(query, req.Query)
	} else {
		rows, err = db.Query(query)
	}
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
